          </div>
        </div>
      )}
    </motion.div>
  );
}

/**
 * MessageItem - Individual message rendering with animations
 *
 * Streaming: Text accumulates via RAF-batched updates for smooth 60fps appearance.
 */
import { useMemo, memo } from "react";
import { motion } from "framer-motion";
import type { Message } from "@normie/types";
import { ThinkingBlock } from "../ThinkingBlock";
import { InlineToolCall } from "../InlineToolCall";
import { AnimatedStream } from "./AnimatedStream";

// Format relative time (e.g., "Just now", "2m ago", "1h ago")
function formatRelativeTime(date: Date): string {
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffSecs = Math.floor(diffMs / 1000);
  const diffMins = Math.floor(diffSecs / 60);
  const diffHours = Math.floor(diffMins / 60);
  const diffDays = Math.floor(diffHours / 24);

  if (diffSecs < 10) return "Just now";
  if (diffSecs < 60) return `${diffSecs}s ago`;
  if (diffMins < 60) return `${diffMins}m ago`;
  if (diffHours < 24) return `${diffHours}h ago`;
  if (diffDays < 7) return `${diffDays}d ago`;
  return date.toLocaleDateString();
}

interface MessageItemProps {
  message: Message;
  isStreaming?: boolean;
}

export const MessageItem = memo(function MessageItem({
  message,
  isStreaming = false,
}: MessageItemProps) {
  const isUser = message.role === "user";

  // Generate a stable timestamp for this message instance
  const timestamp = useMemo(() => new Date(), []);

  if (isUser) {
    return (
      <motion.div
        initial={{ opacity: 0, y: 8 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
        className="flex flex-col gap-0.5 items-end"
      >
        {/* Glass container wrapper - more compact */}
        <div className="inline-block p-1 pb-0.5 rounded-2xl bg-white/40 border border-white/60 shadow-glass">
          <div className="bg-gradient-to-br from-purple-500 to-purple-600 px-3.5 py-2 rounded-2xl max-w-2xl border border-purple-400/50 shadow-purple">
            <p className="text-sm font-normal text-white leading-relaxed">
              {message.content}
            </p>
          </div>
        </div>
        <span className="text-xs font-light text-text-tertiary mr-1.5">
          {formatRelativeTime(timestamp)}
        </span>
      </motion.div>
    );
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
      className="flex flex-col gap-3 max-w-3xl"
    >
      {/* Thinking Block - Shows reasoning process */}
      {message.reasoning && (
        <ThinkingBlock
          content={message.reasoning}
          isStreaming={isStreaming && !message.content}
        />
      )}

      {/* Inline Tool Calls - Shown in stream order */}
      {message.inlineToolCalls && message.inlineToolCalls.length > 0 && (
        <div className="space-y-3">
          {message.inlineToolCalls.map((toolCall) => (
            <InlineToolCall key={toolCall.id} toolCall={toolCall} />
          ))}
        </div>
      )}

      {/* Main Content - smooth streaming text */}
      {message.content && (
        <div>
          <AnimatedStream content={message.content} isStreaming={isStreaming} />
        </div>
      )}

      {/* Empty state when streaming starts - bouncing dots */}
      {isStreaming && !message.content && !message.reasoning && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="flex items-center gap-2 py-1"
        >
          <div className="flex gap-1">
            {[0, 1, 2].map((i) => (
              <motion.div
                key={i}
                className="w-2 h-2 bg-purple-500 rounded-full"
                animate={{ y: [0, -4, 0] }}
                transition={{
                  duration: 0.6,
                  repeat: Infinity,
                  delay: i * 0.15,
                  ease: "easeInOut",
                }}
              />
            ))}
          </div>
          <span className="sr-only">Generating response. Click the stop button in the input to cancel.</span>
        </motion.div>
      )}
    </motion.div>
  );
});

/**
 * Tool icon mapping and categorization
 *
 * Maps tool names to appropriate icons and categories for better UX.
 */
import {
  FileText,
  FilePlus,
  FileEdit,
  Terminal,
  Search,
  Globe,
  FolderOpen,
  Image,
  Database,
  Mail,
  Calendar,
  MessageSquare,
  Code,
  Wrench,
  type LucideIcon,
} from 'lucide-react';

export type ToolCategory = 
  | 'file' 
  | 'shell' 
  | 'search' 
  | 'browser' 
  | 'communication' 
  | 'data' 
  | 'utility'
  | 'unknown';

export interface ToolMeta {
  icon: LucideIcon;
  category: ToolCategory;
  label: string;
}

// Tool name patterns to meta mapping
const toolPatterns: Array<{
  pattern: RegExp;
  meta: ToolMeta;
}> = [
  // File operations
  { pattern: /^read$/i, meta: { icon: FileText, category: 'file', label: 'Read file' } },
  { pattern: /^write$/i, meta: { icon: FilePlus, category: 'file', label: 'Write file' } },
  { pattern: /^edit$/i, meta: { icon: FileEdit, category: 'file', label: 'Edit file' } },
  { pattern: /^create.*file/i, meta: { icon: FilePlus, category: 'file', label: 'Create file' } },
  { pattern: /^delete.*file/i, meta: { icon: FileText, category: 'file', label: 'Delete file' } },
  { pattern: /^file.*/i, meta: { icon: FileText, category: 'file', label: 'File operation' } },

  // Shell/Command
  { pattern: /^bash$/i, meta: { icon: Terminal, category: 'shell', label: 'Run command' } },
  { pattern: /^shell$/i, meta: { icon: Terminal, category: 'shell', label: 'Shell' } },
  { pattern: /^execute$/i, meta: { icon: Terminal, category: 'shell', label: 'Execute' } },
  { pattern: /^run/i, meta: { icon: Terminal, category: 'shell', label: 'Run' } },

  // Search
  { pattern: /^grep$/i, meta: { icon: Search, category: 'search', label: 'Search in files' } },
  { pattern: /^find$/i, meta: { icon: Search, category: 'search', label: 'Find' } },
  { pattern: /^search$/i, meta: { icon: Search, category: 'search', label: 'Search' } },
  { pattern: /^glob$/i, meta: { icon: FolderOpen, category: 'search', label: 'Find files' } },

  // Browser
  { pattern: /^browser/i, meta: { icon: Globe, category: 'browser', label: 'Browser' } },
  { pattern: /^navigate$/i, meta: { icon: Globe, category: 'browser', label: 'Navigate' } },
  { pattern: /^click$/i, meta: { icon: Globe, category: 'browser', label: 'Click' } },
  { pattern: /^screenshot$/i, meta: { icon: Image, category: 'browser', label: 'Screenshot' } },

  // Communication
  { pattern: /^mail$/i, meta: { icon: Mail, category: 'communication', label: 'Email' } },
  { pattern: /^email$/i, meta: { icon: Mail, category: 'communication', label: 'Email' } },
  { pattern: /^calendar$/i, meta: { icon: Calendar, category: 'communication', label: 'Calendar' } },
  { pattern: /^slack$/i, meta: { icon: MessageSquare, category: 'communication', label: 'Slack' } },

  // Data
  { pattern: /^database$/i, meta: { icon: Database, category: 'data', label: 'Database' } },
  { pattern: /^query$/i, meta: { icon: Database, category: 'data', label: 'Query' } },

  // Utility
  { pattern: /^todo/i, meta: { icon: Wrench, category: 'utility', label: 'Todo' } },
  { pattern: /^code.*analy/i, meta: { icon: Code, category: 'utility', label: 'Analyze code' } },
];

/**
 * Get tool metadata (icon, category, label) from tool name
 */
export function getToolMeta(toolName: string): ToolMeta {
  for (const { pattern, meta } of toolPatterns) {
    if (pattern.test(toolName)) {
      return meta;
    }
  }

  // Default fallback
  return {
    icon: Wrench,
    category: 'unknown',
    label: formatToolLabel(toolName),
  };
}

/**
 * Format tool name into a readable label
 */
function formatToolLabel(toolName: string): string {
  // Convert camelCase/PascalCase to spaces
  const spaced = toolName
    .replace(/([a-z])([A-Z])/g, '$1 $2')
    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1 $2');

  // Capitalize first letter
  return spaced.charAt(0).toUpperCase() + spaced.slice(1);
}

/**
 * Get category color classes
 */
export function getCategoryColor(category: ToolCategory): {
  bg: string;
  text: string;
  border: string;
} {
  switch (category) {
    case 'file':
      return {
        bg: 'bg-blue-50',
        text: 'text-blue-600',
        border: 'border-blue-200',
      };
    case 'shell':
      return {
        bg: 'bg-zinc-100',
        text: 'text-zinc-700',
        border: 'border-zinc-300',
      };
    case 'search':
      return {
        bg: 'bg-purple-50',
        text: 'text-purple-600',
        border: 'border-purple-200',
      };
    case 'browser':
      return {
        bg: 'bg-cyan-50',
        text: 'text-cyan-600',
        border: 'border-cyan-200',
      };
    case 'communication':
      return {
        bg: 'bg-orange-50',
        text: 'text-orange-600',
        border: 'border-orange-200',
      };
    case 'data':
      return {
        bg: 'bg-indigo-50',
        text: 'text-indigo-600',
        border: 'border-indigo-200',
      };
    case 'utility':
      return {
        bg: 'bg-zinc-50',
        text: 'text-zinc-600',
        border: 'border-zinc-200',
      };
    default:
      return {
        bg: 'bg-zinc-50',
        text: 'text-zinc-600',
        border: 'border-zinc-200',
      };
  }
}

