/**
 * StreamingText - Smooth streaming with RAF-throttled markdown parsing
 *
 * Technique from Open WebUI's Markdown.svelte:
 * 
 * 1. Use requestAnimationFrame to throttle markdown parsing
 * 2. Skip parsing if there's already a pending update
 * 3. When streaming ends, parse immediately (no throttle)
 *
 * This prevents multiple markdown parses per animation frame,
 * which is what causes jank during streaming.
 */
import { memo, useRef, useEffect, useState, useCallback } from 'react';
import { marked } from 'marked';

interface StreamingTextProps {
  content: string;
  isStreaming: boolean;
  className?: string;
}

function _StreamingText({ content, isStreaming, className = '' }: StreamingTextProps) {
  const [htmlContent, setHtmlContent] = useState('');
  const pendingUpdateRef = useRef<number | null>(null);
  const lastContentRef = useRef('');

  // Parse markdown (expensive operation)
  const parseMarkdown = useCallback((text: string) => {
    if (text === lastContentRef.current) return;
    lastContentRef.current = text;

    try {
      const html = marked.parse(text, { breaks: true, gfm: true }) as string;
      setHtmlContent(html);
    } catch (e) {
      console.error('Markdown parse error:', e);
    }
  }, []);

  // Throttled update handler - THE KEY TECHNIQUE
  useEffect(() => {
    if (!content) return;

    if (!isStreaming) {
      // When done streaming, parse immediately
      if (pendingUpdateRef.current) {
        cancelAnimationFrame(pendingUpdateRef.current);
        pendingUpdateRef.current = null;
      }
      parseMarkdown(content);
    } else if (!pendingUpdateRef.current) {
      // During streaming: only parse if no pending update
      // This throttles to max 1 parse per animation frame
      pendingUpdateRef.current = requestAnimationFrame(() => {
        pendingUpdateRef.current = null;
        parseMarkdown(content);
      });
    }
    // If there IS a pending update, skip - the scheduled one will handle it

    return () => {
      if (pendingUpdateRef.current) {
        cancelAnimationFrame(pendingUpdateRef.current);
        pendingUpdateRef.current = null;
      }
    };
  }, [content, isStreaming, parseMarkdown]);

  if (!content && !isStreaming) return null;

  return (
    <div className={className}>
      <div 
        className="markdown-content text-sm font-light text-zinc-900 leading-relaxed"
        dangerouslySetInnerHTML={{ __html: htmlContent }}
      />

      {isStreaming && (
        <span 
          className="inline-block w-0.5 h-4 bg-zinc-400 ml-0.5 align-text-bottom"
          style={{ animation: 'cursorBlink 0.8s step-end infinite' }}
        />
      )}
    </div>
  );
}

export const StreamingText = memo(_StreamingText);

/**
 * InlineToolCall - Displays tool execution with status and expandable result
 *
 * Features:
 * - Status indicators (running/success/error) with animated ping for running
 * - Tool-specific icons based on category
 * - Collapsible result section
 * - Smooth animations via framer-motion
 */
import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ChevronRight, CheckCircle, XCircle } from 'lucide-react';
import type { InlineToolCall as InlineToolCallType } from '@normie/types';
import { getToolMeta, getCategoryColor } from '@/lib/tool-icons';
import { formatToolPreview } from '@normie/utils';

interface InlineToolCallProps {
  toolCall: InlineToolCallType;
}

export function InlineToolCall({ toolCall }: InlineToolCallProps) {
  const [isExpanded, setIsExpanded] = useState(toolCall.status === 'running');

  const { name, input, status, result } = toolCall;
  const meta = getToolMeta(name);
  const categoryColor = getCategoryColor(meta.category);
  const preview = formatToolPreview(name, input);

  const Icon = meta.icon;

  // Status-specific styles
  const statusStyles = {
    running: {
      container: 'border-amber-200 bg-amber-50/30',
      indicator: (
        <span className="flex items-center gap-1.5">
          <span className="relative flex h-2 w-2">
            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-amber-400 opacity-75"></span>
            <span className="relative inline-flex rounded-full h-2 w-2 bg-amber-500"></span>
          </span>
          <span className="text-xs text-amber-600 font-medium">Running</span>
        </span>
      ),
    },
    success: {
      container: 'border-emerald-200 bg-emerald-50/30',
      indicator: (
        <span className="flex items-center gap-1 text-emerald-600">
          <CheckCircle className="w-3.5 h-3.5" />
          <span className="text-xs font-medium">Done</span>
        </span>
      ),
    },
    error: {
      container: 'border-red-200 bg-red-50/30',
      indicator: (
        <span className="flex items-center gap-1 text-red-600">
          <XCircle className="w-3.5 h-3.5" />
          <span className="text-xs font-medium">Error</span>
        </span>
      ),
    },
  };

  const styles = statusStyles[status];

  // Format result for display
  const resultText =
    typeof result === 'string'
      ? result
      : result !== undefined
        ? JSON.stringify(result, null, 2)
        : null;

  return (
    <motion.div
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
      className={`rounded-lg border shadow-sm transition-colors ${styles.container}`}
    >
      {/* Header */}
      <button
        onClick={() => setIsExpanded(!isExpanded)}
        className="flex items-center gap-3 px-3 py-2.5 w-full hover:bg-black/[0.02] transition-colors text-left"
      >
        {/* Icon with category color */}
        <div className={`p-1.5 rounded-md ${categoryColor.bg} ${categoryColor.border} border`}>
          <Icon className={`w-3.5 h-3.5 ${categoryColor.text}`} strokeWidth={1.5} />
        </div>

        {/* Label and preview */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <span className="text-sm font-medium text-zinc-800">{meta.label}</span>
            {styles.indicator}
          </div>

          {preview && (
            <p className="text-xs text-zinc-500 mt-0.5 truncate font-mono">
              {preview}
            </p>
          )}
        </div>

        {/* Expand arrow */}
        <ChevronRight
          className={`w-4 h-4 text-zinc-400 transition-transform duration-200 ${isExpanded ? 'rotate-90' : ''}`}
          strokeWidth={1.5}
        />
      </button>

      {/* Result section */}
      <AnimatePresence initial={false}>
        {isExpanded && resultText && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
            className="overflow-hidden"
          >
            <div className="px-3 pb-3 pt-2 border-t border-zinc-100">
              <p className="text-xs font-medium text-zinc-400 mb-1.5">Result</p>
              <pre className="text-xs font-mono text-zinc-600 bg-white rounded-md p-2.5 border border-zinc-100 overflow-x-auto max-h-48 overflow-y-auto">
                {resultText.length > 2000
                  ? resultText.substring(0, 2000) + '\n... (truncated)'
                  : resultText}
              </pre>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Running state - show hint to expand */}
      {status === 'running' && !isExpanded && !resultText && (
        <div className="px-3 pb-2.5 pt-1">
          <div className="flex items-center gap-2 text-amber-600/70">
            <span className="text-xs font-light">Click to see progress</span>
          </div>
        </div>
      )}
    </motion.div>
  );
}

/**
 * MessageItem - Individual message rendering with animations
 *
 * Streaming: Text accumulates via RAF-batched updates for smooth 60fps appearance.
 */
import { useMemo, memo } from "react";
import { motion } from "framer-motion";
import type { Message } from "@normie/types";
import { ThinkingBlock } from "../ThinkingBlock";
import { InlineToolCall } from "../InlineToolCall";
import { AnimatedStream } from "./AnimatedStream";

// Format relative time (e.g., "Just now", "2m ago", "1h ago")
function formatRelativeTime(date: Date): string {
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffSecs = Math.floor(diffMs / 1000);
  const diffMins = Math.floor(diffSecs / 60);
  const diffHours = Math.floor(diffMins / 60);
  const diffDays = Math.floor(diffHours / 24);

  if (diffSecs < 10) return "Just now";
  if (diffSecs < 60) return `${diffSecs}s ago`;
  if (diffMins < 60) return `${diffMins}m ago`;
  if (diffHours < 24) return `${diffHours}h ago`;
  if (diffDays < 7) return `${diffDays}d ago`;
  return date.toLocaleDateString();
}

interface MessageItemProps {
  message: Message;
  isStreaming?: boolean;
}

export const MessageItem = memo(function MessageItem({
  message,
  isStreaming = false,
}: MessageItemProps) {
  const isUser = message.role === "user";

  // Generate a stable timestamp for this message instance
  const timestamp = useMemo(() => new Date(), []);

  if (isUser) {
    return (
      <motion.div
        initial={{ opacity: 0, y: 8 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
        className="flex flex-col gap-0.5 items-end"
      >
        {/* Glass container wrapper - more compact */}
        <div className="inline-block p-1 pb-0.5 rounded-2xl bg-white/40 border border-white/60 shadow-glass">
          <div className="bg-gradient-to-br from-purple-500 to-purple-600 px-3.5 py-2 rounded-2xl max-w-2xl border border-purple-400/50 shadow-purple">
            <p className="text-sm font-normal text-white leading-relaxed">
              {message.content}
            </p>
          </div>
        </div>
        <span className="text-xs font-light text-text-tertiary mr-1.5">
          {formatRelativeTime(timestamp)}
        </span>
      </motion.div>
    );
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
      className="flex flex-col gap-3 max-w-3xl"
    >
      {/* Thinking Block - Shows reasoning process */}
      {message.reasoning && (
        <ThinkingBlock
          content={message.reasoning}
          isStreaming={isStreaming && !message.content}
        />
      )}

      {/* Inline Tool Calls - Shown in stream order */}
      {message.inlineToolCalls && message.inlineToolCalls.length > 0 && (
        <div className="space-y-3">
          {message.inlineToolCalls.map((toolCall) => (
            <InlineToolCall key={toolCall.id} toolCall={toolCall} />
          ))}
        </div>
      )}

      {/* Main Content - smooth streaming text */}
      {message.content && (
        <div>
          <AnimatedStream content={message.content} isStreaming={isStreaming} />
        </div>
      )}

      {/* Empty state when streaming starts - bouncing dots */}
      {isStreaming && !message.content && !message.reasoning && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="flex items-center gap-2 py-1"
        >
          <div className="flex gap-1">
            {[0, 1, 2].map((i) => (
              <motion.div
                key={i}
                className="w-2 h-2 bg-purple-500 rounded-full"
                animate={{ y: [0, -4, 0] }}
                transition={{
                  duration: 0.6,
                  repeat: Infinity,
                  delay: i * 0.15,
                  ease: "easeInOut",
                }}
              />
            ))}
          </div>
          <span className="sr-only">Generating response. Click the stop button in the input to cancel.</span>
        </motion.div>
      )}
    </motion.div>
  );
});

