/**
 * Raw API chat response shape
 */
interface ApiChatResponse {
  id: string | number;
  title?: string;
  provider?: string;
  model?: string;
  sessionId?: string;
  updatedAt?: string | Date | number;
  messages?: ApiMessageResponse[];
  todos?: Todo[];
  toolCalls?: ToolCall[];
}

/**
 * Raw API message response shape
 */
interface ApiMessageResponse {
  id?: string | number;
  role: string;
  content: string;
  reasoning?: string;
  toolCalls?: ToolCall[];
  inlineToolCalls?: ToolCall[];
}

/**
 * Transform API message to local Message type
 */
function transformApiMessage(msg: ApiMessageResponse): Message {
  return {
    id: msg.id ? String(msg.id) : generateId(),
    role: msg.role === 'user' ? 'user' : 'assistant',
    content: msg.content || '',
    reasoning: msg.reasoning,
    toolCalls: msg.toolCalls,
    inlineToolCalls: msg.inlineToolCalls,
  };
}

/**
 * Transform API chat response to local Chat type
 * 
 * Use this when you need the full chat with messages.
 */
export function transformApiChat(chatData: ApiChatResponse): Chat {
  const messages = (chatData.messages || []).map(transformApiMessage);

  return {
    id: String(chatData.id),
    title: String(chatData.title || 'New chat'),
    provider: (chatData.provider || 'claude') as Provider,
    model: String(chatData.model || ''),
    sessionId: chatData.sessionId ? String(chatData.sessionId) : undefined,
    updatedAt: chatData.updatedAt
      ? new Date(chatData.updatedAt).getTime()
      : Date.now(),
    messages,
    todos: chatData.todos,
    toolCalls: chatData.toolCalls,
  };
}

/**
 * Transform API chat response to local Chat type (without messages)
 * 
 * Use this for chat list views where messages are loaded separately.
 */
export function transformApiChatLite(chatData: ApiChatResponse): Chat {
  return {
    id: String(chatData.id),
    title: String(chatData.title || 'New chat'),
    provider: (chatData.provider || 'claude') as Provider,
    model: String(chatData.model || ''),
    sessionId: chatData.sessionId ? String(chatData.sessionId) : undefined,
    updatedAt: chatData.updatedAt
      ? new Date(chatData.updatedAt).getTime()
      : Date.now(),
    messages: [], // Loaded separately
    todos: undefined,
    toolCalls: undefined,
  };
}

/**
 * Chat API - All chat-related API calls
 * 
 * Uses window.authAPI for chat CRUD and window.electronAPI for streaming.
 */
import type { Chat, Provider } from '@normie/types';

export interface ApiChat {
  id: string | number;
  title?: string;
  provider?: string;
  model?: string;
  sessionId?: string;
  updatedAt?: string | Date;
  messages?: Chat['messages'];
  todos?: Chat['todos'];
  toolCalls?: Chat['toolCalls'];
}

export const chatApi = {
  /**
   * Get all chats for a workspace
   */
  list: async (workspaceId: string): Promise<ApiChat[]> => {
    if (!window.authAPI) throw new Error('Auth API not available');
    return window.authAPI.getChats(workspaceId);
  },

  /**
   * Get a single chat with messages
   */
  get: async (chatId: string): Promise<ApiChat> => {
    if (!window.authAPI) throw new Error('Auth API not available');
    return window.authAPI.getChat(chatId);
  },

  /**
   * Delete a chat
   */
  delete: async (chatId: string): Promise<void> => {
    if (!window.authAPI) throw new Error('Auth API not available');
    await window.authAPI.deleteChat(chatId);
  },

  /**
   * Send a message and get a streaming response
   * Returns an object with a read() method for streaming
   */
  send: async (params: {
    content: string;
    chatId: string;
    provider: Provider;
    model: string;
    workspaceId: string | null;
    userId: string;
  }): Promise<{ read: () => Promise<{ done: boolean; value?: string }> }> => {
    const { content, chatId, provider, model, workspaceId, userId } = params;

    if (!window.electronAPI) {
      throw new Error('Electron API not available');
    }

    const response = await window.electronAPI.sendMessage(
      content,
      chatId,
      provider,
      model,
      workspaceId,
      userId
    );

    return response.getReader();
  },

  /**
   * Abort an ongoing chat stream
   */
  abort: async (chatId: string, provider: Provider): Promise<void> => {
    window.electronAPI?.abortCurrentRequest();
    await window.electronAPI?.stopQuery(chatId, provider);
  },
};

