/**
 * useApiKeys - TanStack Query hook for managing API keys
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { authAPI } from '@/lib/api/client';

export interface ApiKeyInfo {
  id: string;
  provider: string;
  keyPreview: string | null;
  isValid: boolean;
  createdAt: string;
  lastUsedAt: string | null;
}

export const apiKeyKeys = {
  all: ['apiKeys'] as const,
  list: () => [...apiKeyKeys.all, 'list'] as const,
};

/**
 * Hook to list all API keys for the current user
 */
export function useApiKeys() {
  return useQuery({
    queryKey: apiKeyKeys.list(),
    queryFn: async () => {
      const response = await authAPI.fetch('/api/api-keys');
      if (!response.ok) {
        throw new Error('Failed to fetch API keys');
      }
      const data = await response.json();
      return data.keys as ApiKeyInfo[];
    },
    staleTime: 5 * 60 * 1000, // 5 minutes
  });
}

/**
 * Hook to save an API key for a provider
 */
export function useSaveApiKey() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ provider, apiKey }: { provider: string; apiKey: string }) => {
      const response = await authAPI.fetch(`/api/api-keys/${provider}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ apiKey }),
      });

      if (!response.ok) {
        const error = await response.json().catch(() => ({ error: 'Failed to save API key' }));
        throw new Error(error.error || 'Failed to save API key');
      }

      return response.json();
    },
    onSuccess: () => {
      // Invalidate and refetch the keys list
      queryClient.invalidateQueries({ queryKey: apiKeyKeys.list() });
    },
  });
}

/**
 * Hook to delete an API key for a provider
 */
export function useDeleteApiKey() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (provider: string) => {
      const response = await authAPI.fetch(`/api/api-keys/${provider}`, {
        method: 'DELETE',
      });

      if (!response.ok) {
        throw new Error('Failed to delete API key');
      }

      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: apiKeyKeys.list() });
    },
  });
}

import { Router, Request, Response } from 'express';
import { requireAuth } from '../auth/index.js';
import { saveApiKey, listApiKeys, deleteApiKey } from '../auth/api-keys.js';

const router = Router();

router.use(requireAuth);

// Request body types
interface SaveApiKeyBody {
  apiKey: string;
}

// Valid API key providers
const VALID_PROVIDERS = [
  'anthropic', 'openai', 'kimi', 'opencode', 'google', 'mistral',
  'groq', 'openrouter', 'xai',
  'bedrock', 'azure'
] as const;
type ValidProvider = typeof VALID_PROVIDERS[number];

// ============================================
// LIST API KEYS
// ============================================
router.get('/', async (req: Request, res: Response) => {
  try {
    const keys = await listApiKeys(req.userId!);
    res.json({ keys });
  } catch (err) {
    console.error('[API-KEYS] List error:', err);
    res.status(500).json({ error: 'Failed to list API keys' });
  }
});

// ============================================
// SAVE API KEY
// ============================================
router.post('/:provider', async (req: Request, res: Response) => {
  try {
    const provider = req.params.provider as string;
    const { apiKey } = req.body as SaveApiKeyBody;

    if (!apiKey) {
      return res.status(400).json({ error: 'API key required' });
    }

    // Validate provider
    if (!VALID_PROVIDERS.includes(provider as ValidProvider)) {
      return res.status(400).json({ error: `Invalid provider. Valid: ${VALID_PROVIDERS.join(', ')}` });
    }

    const key = await saveApiKey(req.userId!, provider, apiKey);
    res.json(key);
  } catch (err) {
    console.error('[API-KEYS] Save error:', err);
    res.status(500).json({ error: 'Failed to save API key' });
  }
});

// ============================================
// DELETE API KEY
// ============================================
router.delete('/:provider', async (req: Request, res: Response) => {
  try {
    const provider = req.params.provider as string;
    await deleteApiKey(req.userId!, provider);
    res.json({ success: true });
  } catch (err) {
    console.error('[API-KEYS] Delete error:', err);
    res.status(500).json({ error: 'Failed to delete API key' });
  }
});

export default router;

