        if (!envKey) {
          return { configured: false, options: {}, error: `No API key configured for ${provider}` };
        }
        return { configured: true, options: { apiKey: envKey } };
      }
      return { configured: true, options: { apiKey: storedCredentials } };

    case 'bedrock':
      // Parse stored Bedrock credentials JSON
      if (!storedCredentials) {
        return { configured: false, options: {}, error: 'No AWS Bedrock credentials configured' };
      }
      const bedrockCreds = JSON.parse(storedCredentials);
      if (bedrockCreds.authMode === 'profile') {
        return { configured: true, options: { profile: bedrockCreds.profile } };
      } else {
        // Access key mode - need to set AWS env vars temporarily (still risky!)
        // OR use AWS SDK credential provider
        return { configured: true, options: { 
          region: bedrockCreds.region,
          // Can't safely pass access keys per-request with current SDK design
          // Need alternative approach
        }};
      }

    case 'azure':
      // Parse stored Azure credentials
      if (!storedCredentials) {
        return { configured: false, options: {}, error: 'No Azure credentials configured' };
      }
      const azureCreds = JSON.parse(storedCredentials);
      return {
        configured: true,
        options: {
          apiKey: azureCreds.apiKey,
          azureResourceName: azureCreds.resourceName,
          azureDeploymentName: azureCreds.deploymentName,
          azureApiVersion: azureCreds.apiVersion
        }
      };

    default:
      // Unknown provider - try simple API key
      return { configured: !!storedCredentials, options: { apiKey: storedCredentials || '' } };
  }
}
